python - <<'EOF'
import json, os

print("=== factor files ===")
for fn in sorted(os.listdir('factors')):
    if fn.endswith('.json') and not fn.endswith('.bak'):
        path = os.path.join('factors', fn)
        try:
            with open(path) as f:
                data = json.load(f)
            # summarize keys
            if isinstance(data, dict):
                keys = list(data.keys())
                print(f"{fn}: keys={keys}")
                # print compact metadata if available
                meta = {k: v for k, v in data.items() if not isinstance(v, (list, dict))}
                print("   meta:", meta)
                for k, v in data.items():
                    if isinstance(v, dict):
                        print(f"   {k}: {list(v.keys())[:10]}")
                    elif isinstance(v, list):
                        print(f"   {k}: list len={len(v)}")
            else:
                print(f"{fn}: type={type(data)}")
        except Exception as e:
            print(f"{fn}: ERROR {e}")

print()
print("=== rejected dir ===")
for fn in sorted(os.listdir('factors/rejected')):
    print("rejected:", fn)
EOF

