python - <<'EOF'
import json

factors = {
    "mom_120d_skip5":   {"ic": 0.0521, "icir": 0.1381, "dir": 1},
    "vol_of_vol20x60":  {"ic": 0.0424, "icir": 0.1206, "dir": 1},
    "mom_10d_skip5":    {"ic": 0.0409, "icir": 0.1183, "dir": 1},
    "vix_beta_cond_60x20": {"ic": -0.0382, "icir": -0.0927, "dir": -1},
}

q = {k: abs(v["ic"]) * abs(v["icir"]) for k, v in factors.items()}
total = sum(q.values())
print("q values:", {k: round(v, 6) for k, v in q.items()}, "total:", round(total, 6))

weights = {k: v / total for k, v in q.items()}
for k, w in weights.items():
    print(f"{k}: q={q[k]:.6f} w={w:.4f} dir={factors[k]['dir']}")
print("sum weights:", round(sum(weights.values()), 6))

ensemble = {
    "schema_version": 1,
    "selected_factors": [
        {"factor_id": k, "weight": round(weights[k], 4), "direction": factors[k]["dir"]}
        for k in sorted(weights, key=lambda x: -weights[x])
    ],
    "method": "quality_ic_tilt",
}
print(json.dumps(ensemble, indent=2))
with open("factors/factor_ensemble.json", "w") as f:
    json.dump(ensemble, f, indent=2)
print("written.")
EOF

